from __future__ import annotations

from pathlib import Path
import json
import os
import re
import sys

ROOT = Path('.')
MAN = ROOT / 'manifiestos'
CANON = MAN / 'CANONICAL_FILENAMES.json'
NEOAX = ROOT / 'neoaxiomas'

