DIRECT_ALIASES = {
    'Neodialectica Framework™': Path('README.md'),
    'Lupa Neodialéctica™': Path('analisis/publicos/2026-07-13-religion-identidad-dogma-conciencia-neodialectica_ES_EN.md'),
}

GENEALOGY_PREFIX = '**Relación genealógica / Genealogical relation:**'
RELATION_PREFIXES = ('**Relaciones principales / Main relations:**', '**Relaciones raíz / Root relations:**', GENEALOGY_PREFIX)
MD_LINK_RE = re.compile(r'\[([^\]]+)\]\(([^)]+)\)')
TM_RE = re.compile(r'([A-ZÁÉÍÓÚÜÑa-záéíóúüñ0-9][^,;:.\n]*?™)')
ROMAN_TARGET_RE = re.compile(r'(?<!\[)(?<![A-Z])([IVXLCDM]+)\s*·\s*([^,;.\[\]\n]*?™)')
BARE_ROMAN_RE = re.compile(r'(?<!\[)(?<![A-Z])([IVXLCDM]+)(?![A-Z\]])(?=\s*(?:,|·|$|\by\b|\be\b|\band\b))')
RAW_INFINITY_RE = re.compile(r'(?<!\[)∞(?!\])')
RAW_NEOAX_RE = re.compile(r'(?<!\[)(?<![A-Z0-9-])(C-NAX-\d+|NAX-\d+)(?![A-Z0-9-])(?!\])')
# Repairs generated by historic/non-idempotent passes.
MALFORMED_NAX10_RE = re.compile(r'\[NAX-10\]\([^)]*?\[NAX-10\]\(([^)]+NAX-10_FUEGO_DE_AGUA_TOTALIDAD_ELEMENTAL_ES_EN\.md)\)_FUEGO_DE_AGUA_TOTALIDAD_ELEMENTAL_ES_EN\.md\)')
MALFORMED_TRAILING_NEOAX_RE = re.compile(r'(?<!\[)(C-NAX-\d+|NAX-\d+)\]\([^)]+\)')
ORPHAN_OPEN_NEOAX_RE = re.compile(r'\[(C-NAX-\d+|NAX-\d+)(?!\]\()')
NESTED_IDENTICAL_LINK_RE = re.compile(r'\[([^\[\]]*?)\[([^\]]+)\]\(([^)]+)\)([^\[\]]*?)\]\(\3\)')
MALFORMED_ROMAN_LABEL_RE = re.compile(r'(?<!\])\[([IVXLCDM]+)\s*·\s*([^,\n]+?)(?=,\s*\[)')


def load_entries() -> dict[str, dict[str, str]]:
    return json.loads(CANON.read_text(encoding='utf-8'))['entries']


def relative_target(source: Path, repo_path: str | Path) -> str:
    return Path(os.path.relpath(ROOT / repo_path, start=source.parent)).as_posix()


def verified_href(source: Path, roman: str, entries: dict[str, dict[str, str]]) -> str | None:
    entry = entries.get(roman)
    canonical = entry.get('canonical') if entry else None
    return relative_target(source, canonical) if canonical and (ROOT / canonical).exists() else None


def verified_direct_href(source: Path, repo_path: Path) -> str | None:
    return relative_target(source, repo_path) if (ROOT / repo_path).exists() else None


def verified_infinity_href(source: Path) -> str | None:
    target = MAN / 'INFINITO_neo0_puerta_abierta_fractal_leonidas_ES_EN.md'
    return relative_target(source, target) if target.exists() else None


def verified_neoaxiom_href(source: Path, identifier: str) -> str | None:
    target = NEOAX / ('NAX-10_FUEGO_DE_AGUA_TOTALIDAD_ELEMENTAL_ES_EN.md' if identifier == 'NAX-10' else 'README.md')
    return relative_target(source, target) if target.exists() else None


def protect_links(line: str) -> tuple[str, list[str]]:
    spans: list[str] = []
    def repl(m: re.Match[str]) -> str:
        spans.append(m.group(0)); return f'@@MDLINK_{len(spans)-1}@@'
    return MD_LINK_RE.sub(repl, line), spans


def restore_links(line: str, spans: list[str]) -> str:
    for i, value in enumerate(spans): line = line.replace(f'@@MDLINK_{i}@@', value)
    return line


def normalize_malformed_links(line: str, source: Path, entries: dict[str, dict[str, str]]) -> str:
    # Collapse nested links only when both layers point to exactly the same destination.
    while True:
        new = NESTED_IDENTICAL_LINK_RE.sub(lambda m: f'[{m.group(1)}{m.group(2)}{m.group(4)}]({m.group(3)})', line)
        if new == line: break
        line = new
    line = MALFORMED_NAX10_RE.sub(lambda m: f'[NAX-10]({m.group(1)})', line)
    line = MALFORMED_TRAILING_NEOAX_RE.sub(lambda m: m.group(1), line)
    # Remove orphan '[' left before a Neoaxiom id; valid [ID](href) spans do not match.
    line = ORPHAN_OPEN_NEOAX_RE.sub(lambda m: m.group(1), line)
    # Historic lines may start a Roman pseudo-link but never provide ](href).
    def roman_repl(m: re.Match[str]) -> str:
        roman, label = m.group(1), m.group(2).strip()
        href = verified_href(source, roman, entries)
        return f'[{roman} · {label}]({href})' if href else m.group(0)
    return MALFORMED_ROMAN_LABEL_RE.sub(roman_repl, line)


def transform_outside_links(line: str, transform) -> str:
    protected, spans = protect_links(line)
    return restore_links(transform(protected), spans)


def link_explicit_roman_targets(line: str, source: Path, entries: dict[str, dict[str, str]]) -> tuple[str, list[str]]:
    unresolved: list[str] = []
    def do(text: str) -> str:
        def repl(m: re.Match[str]) -> str:
            roman, title = m.group(1), m.group(2).strip(); label = f'{roman} · {title}'
            href = verified_href(source, roman, entries)
            if not href: unresolved.append(label); return m.group(0)
            return f'[{label}]({href})'
        return ROMAN_TARGET_RE.sub(repl, text)
    return transform_outside_links(line, do), unresolved


def link_bare_roman_targets(line: str, source: Path, entries: dict[str, dict[str, str]]) -> tuple[str, list[str]]:
    unresolved: list[str] = []
    def do(text: str) -> str:
        def repl(m: re.Match[str]) -> str:
            roman = m.group(1); href = verified_href(source, roman, entries)
            if not href: unresolved.append(roman); return roman
            return f'[{roman}]({href})'
        return BARE_ROMAN_RE.sub(repl, text)
    return transform_outside_links(line, do), unresolved


def link_infinity(line: str, source: Path) -> tuple[str, list[str]]:
    href = verified_infinity_href(source)
    if '∞' not in line: return line, []
    if not href: return line, ['∞']
    return transform_outside_links(line, lambda s: RAW_INFINITY_RE.sub(f'[∞]({href})', s)), []


def link_neoaxioms(line: str, source: Path) -> tuple[str, list[str]]:
    unresolved: list[str] = []
    def do(text: str) -> str:
        def repl(m: re.Match[str]) -> str:
            ident = m.group(1); href = verified_neoaxiom_href(source, ident)
            if not href: unresolved.append(ident); return ident
            return f'[{ident}]({href})'
        return RAW_NEOAX_RE.sub(repl, text)
    return transform_outside_links(line, do), unresolved


def link_aliases(line: str, source: Path, entries: dict[str, dict[str, str]]) -> tuple[str, list[str]]:
    unresolved: list[str] = []
    protected, spans = protect_links(line)
    aliases = sorted(set(ALIASES) | set(DIRECT_ALIASES), key=len, reverse=True)
    pattern = re.compile('|'.join(re.escape(a) for a in aliases))
    def repl(m: re.Match[str]) -> str:
        alias = m.group(0)
        if alias in ALIASES:
            href = verified_href(source, ALIASES[alias], entries)
        else:
            href = verified_direct_href(source, DIRECT_ALIASES[alias])
        if not href: unresolved.append(alias); return alias
        return f'[{alias}]({href})'
    # One substitution pass prevents a shorter alias from matching inside a link
    # just generated for a longer alias.
    protected = pattern.sub(repl, protected)
    return restore_links(protected, spans), unresolved


def repair_declared_relation_line(line: str, source: Path, entries: dict[str, dict[str, str]]) -> tuple[str, list[str]]:
    if not line.startswith(RELATION_PREFIXES): return line, []
    unresolved: list[str] = []
    new_line = normalize_malformed_links(line, source, entries)
    for fn in (link_explicit_roman_targets, link_bare_roman_targets):
        new_line, xs = fn(new_line, source, entries); unresolved.extend(xs)
    new_line, xs = link_infinity(new_line, source); unresolved.extend(xs)
    new_line, xs = link_neoaxioms(new_line, source); unresolved.extend(xs)
    if line.startswith(GENEALOGY_PREFIX):
        new_line, xs = link_aliases(new_line, source, entries); unresolved.extend(xs)
        residual = MD_LINK_RE.sub('', new_line.split(':**', 1)[-1])
        for raw in TM_RE.findall(residual):
            candidate = raw.strip(' *`')
            for marker in ('profundiza ', 'deepens ', 'integra ', 'integrates ', 'continúa ', 'continues ', 'desarrolla ', 'develops ', 'deriva del conjunto del ', 'formula ', 'Formula ', 'Se relaciona directamente con ', 'la ', 'y ', 'e ', 'and ', 'Abre la cuarta oleada trasladando la '):
                if candidate.startswith(marker): candidate = candidate[len(marker):].strip()
            if candidate.endswith('™') and candidate not in unresolved: unresolved.append(candidate)
    return new_line, unresolved


def manifest_files(entries: dict[str, dict[str, str]]) -> list[Path]:
    """Return material sources only; canonical mirrors are generated afterwards.

    Editing mirrors independently would create a second authority and can hide
    source/mirror drift. Registered legacy sources plus the permanent infinity
    source are the only writable inputs for relational repair.
    """
    paths: set[Path] = set(MAN.glob('[0-9][0-9]_*.md'))
    for entry in entries.values():
        value = entry.get('legacy')
        if value and (ROOT / value).exists():
            paths.add(ROOT / value)
    inf = MAN / 'INFINITO_neo0_puerta_abierta_fractal_leonidas_ES_EN.md'
    if inf.exists():
        paths.add(inf)
    return sorted(paths)


def main() -> int:
    check_only = '--check' in sys.argv; entries = load_entries(); changed: list[str] = []; unresolved_rows: list[str] = []
    for path in manifest_files(entries):
        text = path.read_text(encoding='utf-8'); out: list[str] = []; touched = False
        for lineno, line in enumerate(text.splitlines(), 1):
            repaired, unresolved = repair_declared_relation_line(line, path, entries)
            touched |= repaired != line; out.append(repaired)
            for item in unresolved:
                code = 'UNRESOLVED_GENEALOGICAL_TARGET' if line.startswith(GENEALOGY_PREFIX) else 'UNRESOLVED_RELATIONAL_TARGET'
                unresolved_rows.append(f'{path}:{lineno}: {code}: {item}')
        if touched:
            changed.append(str(path))
            if not check_only: path.write_text('\n'.join(out) + ('\n' if text.endswith('\n') else ''), encoding='utf-8')
    print(f'RELATIONAL_REPAIR_CHANGED={len(changed)}')
    for item in changed: print(f'REPAIRED: {item}')
    for item in unresolved_rows: print(item)
    return 1 if check_only and changed else 0

if __name__ == '__main__': raise SystemExit(main())
